package app.quietreader;

import app.quietreader.Models.*;
import app.quietreader.discovery.HotCandidate;
import org.json.*;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

/** Synthetic unique Chinese prose is a structural oracle, not semantic/news quality evidence. */
public class ArticleProgressEvidenceTest {
    private static final long NOW=1800000000000L;
    private static final String SCOPE=HotCandidate.hash("synthetic-session-and-namespace");
    private String prose(int seed){Random random=new Random(seed);StringBuilder result=new StringBuilder();for(int n=0;n<300;n++)result.append((char)(0x4e00+random.nextInt(3000)));return result.toString();}
    private Document before(){Document doc=new Document();doc.url="https://www.ithome.com/0/990/101.htm";doc.title="原标题";doc.cachedAt=NOW-3000;doc.sourceModifiedAt=NOW-4000;doc.sourceUpdateEvidence=ArticleUpdateEvidence.VERSION;Section body=new Section("body","正文",false);for(int n=0;n<6;n++)body.blocks.add(new Block("text",prose(n)));doc.sections.add(body);doc.blocks.addAll(body.blocks);return doc;}
    private Document after(){Document doc=before();doc.cachedAt=NOW;doc.sourceModifiedAt=NOW-1000;doc.sections.get(0).blocks.add(new Block("text","【最新进展】"+prose(90)));doc.sections.get(0).blocks.add(new Block("text",prose(91)));return doc;}
    private ArticleProgressEvidence.Snapshot capture(Document doc){return ArticleProgressEvidence.capture(Source.ITHOME,doc,SCOPE,NOW);}
    private long progress(Document before,Document after){return ArticleProgressEvidence.verifiedProgress(capture(before),capture(after),NOW-2000,NOW);}
    @Test public void substantialExplicitlyMarkedRevisionCanBypassOlderPresentation(){assertEquals(NOW-1000,progress(before(),after()));}
    @Test public void differentArticleCanCarryExplicitFollowupButDoesNotBecomeSameArticleRevision(){Document next=after();next.url="https://www.ithome.com/0/990/102.htm";ArticleProgressEvidence.Snapshot original=capture(before()),followup=capture(next);assertEquals(0,ArticleProgressEvidence.verifiedProgress(original,followup,NOW-2000,NOW));assertEquals(NOW-1000,ArticleProgressEvidence.verifiedFollowup(original,followup,NOW-2000,NOW));}
    @Test public void duplicateRepostAndUnmarkedFollowupDoNotBypassCooldown(){Document next=before();next.url="https://www.ithome.com/0/990/102.htm";next.cachedAt=NOW;next.sourceModifiedAt=NOW-1000;assertEquals(0,ArticleProgressEvidence.verifiedFollowup(capture(before()),capture(next),NOW-2000,NOW));next=after();next.url="https://www.ithome.com/0/990/102.htm";next.sections.get(0).blocks.set(6,new Block("text",prose(90)));assertEquals(0,ArticleProgressEvidence.verifiedFollowup(capture(before()),capture(next),NOW-2000,NOW));}
    @Test public void unrelatedBodiesAndSmallCorrectionsAtNewUrlDoNotBecomeFollowup(){Document next=after();next.url="https://www.ithome.com/0/990/102.htm";next.sections.get(0).blocks.clear();for(int n=100;n<108;n++)next.sections.get(0).blocks.add(new Block("text",(n==100?"【后续报道】":"")+prose(n)));assertEquals(0,ArticleProgressEvidence.verifiedFollowup(capture(before()),capture(next),NOW-2000,NOW));next=before();next.url="https://www.ithome.com/0/990/102.htm";next.cachedAt=NOW;next.sourceModifiedAt=NOW-1000;next.sections.get(0).blocks.add(new Block("text","【更新】报道中一处标点已经修改。"));assertEquals(0,ArticleProgressEvidence.verifiedFollowup(capture(before()),capture(next),NOW-2000,NOW));}
    @Test public void followupMustPostdateActualPresentationAndCannotUseAnUnseenBaseline(){Document next=after();next.url="https://www.ithome.com/0/990/102.htm";ArticleProgressEvidence.Snapshot original=capture(before()),followup=capture(next);assertEquals(0,ArticleProgressEvidence.verifiedFollowup(original,followup,NOW-500,NOW));assertEquals(0,ArticleProgressEvidence.verifiedFollowup(original,followup,NOW-3500,NOW));assertEquals(0,ArticleProgressEvidence.verifiedFollowup(original,followup,NOW-2000,NOW-1));assertEquals(0,ArticleProgressEvidence.verifiedFollowup(original,capture(after()),NOW-2000,NOW));}
    @Test public void workerInputOwnsStringsAndScalarsBeforeMutableReaderChanges(){Document doc=after();ArticleProgressEvidence.Input input=ArticleProgressEvidence.freeze(Source.ITHOME,doc,SCOPE,NOW);assertNotNull(input);doc.sections.clear();doc.blocks.clear();doc.url="https://www.ithome.com/0/990/999.htm";doc.sourceModifiedAt=0;doc.cachedAt=NOW+1;assertEquals(NOW-1000,ArticleProgressEvidence.verifiedProgress(capture(before()),input.finish(NOW),NOW-2000,NOW));}
    @Test public void frozenInputCannotFinishAfterClockRollback(){ArticleProgressEvidence.Input input=ArticleProgressEvidence.freeze(Source.ITHOME,after(),SCOPE,NOW);assertNull(input.finish(NOW-1));}
    @Test public void standaloneSimplifiedAndTraditionalUpdateHeadingsMarkFollowingProse(){for(String heading:List.of("最新进展","最新進展","補充報道")){Document doc=after();List<Block> blocks=doc.sections.get(0).blocks;blocks.set(6,new Block("text",heading));blocks.add(7,new Block("text",prose(90)));assertEquals(heading,NOW-1000,progress(before(),doc));}}
    @Test public void timestampOnlyAndTitleMetadataEditsDoNotBecomeProgress(){Document doc=before();doc.cachedAt=NOW;doc.sourceModifiedAt=NOW-1000;doc.title="最新回应";doc.byline="新作者";doc.metadataHash=HotCandidate.hash("new headline");assertEquals(0,progress(before(),doc));}
    @Test public void substantialUnmarkedAdditionsStayCooled(){Document doc=after();doc.sections.get(0).blocks.set(6,new Block("text",prose(90)));assertEquals(0,progress(before(),doc));}
    @Test public void repeatedAndReorderedProseCannotManufactureNovelty(){Document doc=after();List<Block> blocks=doc.sections.get(0).blocks;blocks.remove(7);blocks.set(6,new Block("text","【更新】"+prose(0)));Collections.reverse(blocks);assertEquals(0,progress(before(),doc));}
    @Test public void punctuationAndWhitespaceAreNotInformation(){Document doc=after();List<Block> blocks=doc.sections.get(0).blocks;blocks.clear();for(int n=0;n<6;n++)blocks.add(new Block("text",(n==0?"【更新】":"")+prose(n).replace("一","一， ")));assertEquals(0,progress(before(),doc));}
    @Test public void smallTypoEditsAreNotWholeParagraphNovelty(){Document doc=after();List<Block> blocks=doc.sections.get(0).blocks;blocks.subList(6,blocks.size()).clear();String original=blocks.get(0).value;blocks.set(0,new Block("text","【更新】"+original.substring(0,80)+"甲乙"+original.substring(82)));assertEquals(0,progress(before(),doc));}
    @Test public void singleCharacterInsertionCannotShiftAllLaterSamples(){Document doc=after();List<Block> blocks=doc.sections.get(0).blocks;blocks.subList(6,blocks.size()).clear();String original=blocks.get(0).value;blocks.set(0,new Block("text","【更新】"+original.substring(0,20)+"甲"+original.substring(20)));assertEquals(0,progress(before(),doc));}
    @Test public void unrelatedReplacementAtSameUrlIsNotRevision(){Document doc=after();doc.sections.get(0).blocks.clear();for(int n=100;n<108;n++)doc.sections.get(0).blocks.add(new Block("text",(n==100?"【更新】":"")+prose(n)));assertEquals(0,progress(before(),doc));}
    @Test public void sourceTimestampMustAdvancePastAcquisitionAndLastSeen(){Document doc=after();doc.sourceModifiedAt=NOW-3500;assertEquals(0,progress(before(),doc));doc.sourceModifiedAt=NOW-1000;assertEquals(0,ArticleProgressEvidence.verifiedProgress(capture(before()),capture(doc),NOW-500,NOW));}
    @Test public void scopeAndArticleIdentityCannotBeTransferred(){ArticleProgressEvidence.Snapshot baseline=capture(before());assertEquals(0,ArticleProgressEvidence.verifiedProgress(baseline,ArticleProgressEvidence.capture(Source.ITHOME,after(),HotCandidate.hash("another-account"),NOW),NOW-2000,NOW));Document doc=after();doc.url="https://www.ithome.com/0/990/102.htm";assertEquals(0,ArticleProgressEvidence.verifiedProgress(baseline,capture(doc),NOW-2000,NOW));}
    @Test public void paginationLoginAndPartialContentAreExcluded(){Document doc=after();doc.nextUrl=doc.url+"?page=2";assertNull(capture(doc));doc=after();doc.loginRequired=true;assertNull(capture(doc));doc=after();doc.notice="仅加载部分内容";assertNull(capture(doc));doc=after();doc.virtualDiscussion=true;assertNull(capture(doc));}
    @Test public void commentsAndNestedRepliesCannotSupplyProgress(){Document doc=after();Section comments=new Section("comments","回复",false);comments.blocks.add(new Block("text","【更新】"+prose(92)));doc.sections.add(comments);assertNull(capture(doc));doc=after();doc.sections.get(0).nestedReply=true;assertNull(capture(doc));}
    @Test public void oversizedAndUnversionedBodiesFailClosed(){Document doc=after();doc.sourceUpdateEvidence="future";assertNull(capture(doc));doc=after();doc.sections.get(0).blocks.add(new Block("text","新".repeat(ArticleProgressEvidence.MAX_CHARS)));assertNull(capture(doc));}
    @Test public void boundedHashOnlyRoundTripPreservesDecision()throws Exception{ArticleProgressEvidence.Snapshot baseline=capture(before()),changed=capture(after());JSONObject json=changed.json();assertFalse(json.toString().contains(after().title));assertFalse(json.toString().contains(prose(90)));assertEquals(NOW-1000,ArticleProgressEvidence.verifiedProgress(ArticleProgressEvidence.Snapshot.read(baseline.json(),NOW),ArticleProgressEvidence.Snapshot.read(json,NOW),NOW-2000,NOW));}
    @Test public void futureOrMalformedSerializedEvidenceIsRejected()throws Exception{JSONObject json=capture(after()).json();json.put("version","future");assertNull(ArticleProgressEvidence.Snapshot.read(json,NOW));json=capture(after()).json().put("acquiredAt",NOW+1);assertNull(ArticleProgressEvidence.Snapshot.read(json,NOW));json=capture(after()).json().put("modifiedAt",Long.toString(NOW-1000));assertNull(ArticleProgressEvidence.Snapshot.read(json,NOW));json=capture(after()).json().put("marked",new JSONArray().put("bad-hash"));assertNull(ArticleProgressEvidence.Snapshot.read(json,NOW));}
}
